def calcola_ordine(apps, schema_editor):
    Lotto = apps.get_model("asta", "Lotto")
    for l in Lotto.objects.all():
        m = re.match(r"\d+", l.numero or "")
        l.ordine = int(m.group()) if m else 0
        l.save(update_fields=["ordine"])


